package com.realestate.duediligence.controller;
import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.realestate.duediligence.dto.*; import com.realestate.duediligence.service.*;
@RestController @RequestMapping("/api/reports") @CrossOrigin(origins="*")
public class ReportController { private final PropertyService propertyService; private final RiskSummaryService riskSummaryService; private final DocumentService documentService; private final PermitService permitService; public ReportController(PropertyService p,RiskSummaryService r,DocumentService d,PermitService pe){propertyService=p;riskSummaryService=r;documentService=d;permitService=pe;} @GetMapping("/{propertyId}") public ResponseEntity<PropertyReportResponse> getReport(@PathVariable Integer propertyId){return ResponseEntity.ok(PropertyReportResponse.builder().property(propertyService.getById(propertyId)).riskSummary(riskSummaryService.getRiskSummary(propertyId)).documents(documentService.getDocuments(propertyId)).permits(permitService.getPermits(propertyId)).build());} }
